def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    markers = {(r, c) for r in range(h) for c in range(w)
               if grid[r][c] != background}

    out = [row[:] for row in grid]

    # Connect consecutive markers on each row.
    for r in range(h):
        cols = [c for rr, c in markers if rr == r]
        cols.sort()
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3

    # Connect consecutive markers on each column.
    for c in range(w):
        rows = [r for r, cc in markers if cc == c]
        rows.sort()
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                out[r][c] = 3

    return out
